deploy.startCommand:
/bin/sh -c 'HASH=$(caddy hash-password --plaintext "$LAMINAR_PASSWORD") && printf ":%s {
 handle /healthz {
  respond 200
 }
 handle /v1/* {
  reverse_proxy %s:8000
 }
 handle {
  basic_auth {
   %s %s
  }
  reverse_proxy %s:5667 {
   header_up -Authorization
  }
 }
}
" "$PORT" "$APP_SERVER_HOST" "$LAMINAR_USERNAME" "$HASH" "$FRONTEND_HOST" > /etc/caddy/Caddyfile && exec caddy run --config /etc/caddy/Caddyfile --adapter caddyfile'
